function mergeIntervals(intervals) {
  const sorted = [...intervals].sort((a, b) => a[0] - b[0]), merged = [] //@init
  for (const [start, end] of sorted) { //@loop
    const last = merged[merged.length - 1]
    if (last && start <= last[1]) last[1] = Math.max(last[1], end) //@extend
    else merged.push([start, end]) //@push
  }
  return merged //@done
}

