function coveredLength(intervals) {
  const sorted = [...intervals].sort((a, b) => a[0] - b[0])
  let total = 0
  let reach = -Infinity // furthest end covered so far
  for (const [start, end] of sorted) {
    // Only the part of [start, end] beyond reach is new. Count just that.
    total += end - start
  }
  return total
}

